"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { CircleHelp, Search, X } from "@/components/ui/icons";

// Search Field: generated by UIX from the design system. Same variants and sizes as the Figma component.

const searchFieldVariants = cva(
  "flex w-full items-center gap-2 transition-colors [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary border border-line-default bg-surface focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled rounded-md",
  {
    variants: {
      size: {
        sm: "h-8 px-3",
        md: "h-10 px-3",
        lg: "h-12 px-4",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface SearchFieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "type" | "prefix">,
    VariantProps<typeof searchFieldVariants> {
  /** Called by the clear button, which shows while the field has a value. */
  onClear?: () => void;
  /** Shortcut hint (for example a Kbd) shown while the field is empty. */
  shortcut?: React.ReactNode;
  /** Avatar at the start (for example <Avatar size="xs" initials="AB" />). */
  leadingAvatar?: React.ReactNode;
  /** Icon at the start. */
  leadingIcon?: React.ReactNode;
  /** Selector or text at the start, for example "Email ▾". */
  leadingContent?: React.ReactNode;
  /** Hairline after the leading parts. */
  leadingDivider?: boolean;
  /** Fixed text before the value, for example "https://". */
  prefix?: React.ReactNode;
  /** Tag chips before the value. */
  tags?: React.ReactNode[];
  /** Fixed text after the value, for example ".com". */
  suffix?: React.ReactNode;
  /** Hairline before the trailing parts. */
  trailingDivider?: boolean;
  /** Action at the end, for example a "Copy" button. */
  trailingContent?: React.ReactNode;
  /** Help icon; a string becomes its accessible name and tooltip. */
  helpIcon?: boolean | string;
  /** Icon at the end. */
  trailingIcon?: React.ReactNode;
}

const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(
  ({ className, size, onClear, shortcut, value, leadingAvatar, leadingIcon, leadingContent, leadingDivider, prefix, tags, suffix, trailingDivider, trailingContent, helpIcon, trailingIcon, ...props }, ref) => (
    <div data-slot="search-field" data-kind="field" role="search" className={cn(searchFieldVariants({ size }), className)}>
      {leadingAvatar}
      {leadingIcon ?? <Search aria-hidden />}
      {leadingContent ? <span className="shrink-0 text-body-medium text-fg-secondary">{leadingContent}</span> : null}
      {leadingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
      {prefix ? <span className="shrink-0 text-body-medium text-fg-secondary">{prefix}</span> : null}
      {tags?.map((tag, index) => (
        <span key={index} className="inline-flex shrink-0 items-center rounded-full bg-subtle text-fg-primary text-label-small px-2 py-0-5">
          {tag}
        </span>
      ))}
      <input ref={ref} type="search" value={value} className="min-w-0 flex-1 bg-transparent outline-none [&::-webkit-search-cancel-button]:hidden text-body-medium text-fg-primary placeholder:text-fg-tertiary disabled:text-fg-disabled" {...props} />
      {suffix ? <span className="shrink-0 text-body-medium text-fg-secondary">{suffix}</span> : null}
      {trailingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
      {trailingContent ? <span className="shrink-0 cursor-pointer text-label-medium text-fg-brand">{trailingContent}</span> : null}
      {helpIcon ? (
        <span role="img" aria-label={typeof helpIcon === "string" ? helpIcon : "Help"} title={typeof helpIcon === "string" ? helpIcon : void 0} className="inline-flex shrink-0 text-icon-secondary">
          <CircleHelp aria-hidden />
        </span>
      ) : null}
      {trailingIcon}
      {onClear && String(value ?? "").length > 0 ? (
        <button type="button" aria-label="Clear search" onClick={onClear} className="shrink-0 cursor-pointer rounded-xs text-icon-secondary hover:text-fg-primary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
          <X aria-hidden />
        </button>
      ) : (
        shortcut
      )}
    </div>
  ),
);
SearchField.displayName = "SearchField";

export { SearchField, searchFieldVariants };
